import bisect
import time
current_time = time.time()
var = 0
ch = [[] for i in range(15)]

def KMP(s, t, idx):
	f = [0 for i in range(len(s) + len(t) + 1)]
	z = t + '#' + s
	for i in range(1, len(z)):
		j = f[i - 1]
		while j > 0 and z[i] != z[j]:
			j = f[j - 1]
		if z[i] == z[j]:
			j += 1
		f[i] = j
	for i in range(len(t) + 1, len(f)):
		if f[i] == len(t):
			ch[idx].append(i - len(t) - len(t))
(n, m) = map(int, input().split())
s = input()
t = []
dp = {}
dp1 = [-1 for i in range(1 << 15)]

def func(idx, mask):
	if time.time() - current_time > 5:
		global var
		var = 1
		return 0
	if mask == (1 << m) - 1:
		return 1
	if idx >= n:
		return 0
	patanahi = (idx, mask)
	if patanahi not in dp:
		ans = 0
		for i in range(m):
			if mask & 1 << i == 0:
				lol = bisect.bisect_left(ch[i], idx)
				if lol != len(ch[i]):
					newidx = ch[i][lol] + len(t[i])
					ans += func(newidx, mask | 1 << i)
		dp[patanahi] = ans
	return dp[patanahi]

def func1(idx, mask):
	if mask == (1 << m) - 1:
		return 1
	if idx >= n:
		return 0
	if dp1[mask] == -1:
		ans = 0
		for i in range(m):
			if mask & 1 << i == 0:
				lol = bisect.bisect_left(ch[i], idx)
				if lol != len(ch[i]):
					newidx = ch[i][lol] + len(t[i])
					ans += func1(newidx, mask | 1 << i)
		dp1[mask] = ans
	return dp1[mask]
for i in range(m):
	tt = input()
	t.append(tt)
	KMP(s, tt, i)
ans = func(0, 0)
if var == 1:
	ans = func1(0, 0)
print(ans)
